UPDATE 02:
Okay well I found the culprit. When I removed this code from my plugin, it works fine again... but am curious as to how this broke the initGraphics
JavaScript:
Object.prototype.matches = function(obj) {
    return Object.keys(this).every(key => {
        return (typeof this[key] === "object" && typeof obj[key] === "object")
            ? this[key].matches(obj[key])
            : this[key] === obj[key];
    });
};
-- Adding this just for context that I have a check for arrays as well that mix-match with the Object version above:
JavaScript:
Array.prototype.matches = function(array) {
    if (!Array.isArray(array) || this.length !== array.length) return false;
    for (let i = 0; i < this.length; i++) {
        const typeA = Object.prototype.toString.call(this[i]);
        const typeB = Object.prototype.toString.call(array[i]);
        if (typeA !== typeB) return false;
        if (this[i] && this[i].matches) { // function must exist
            if (!this[i].matches(array[i])) return false;
        } else if (this[i] !== array[i]) {
            return false;
        }
    }
    return true;
};

