function matchObjects(source, obj) {
    return Object.keys(source).every(key => {
        if (obj.hasOwnProperty(key)) {
            return source[key] instanceof Array && obj[key] instanceof Array
                ? source[key].matches(obj[key])
                : obj[key] === source[key];
        }
        return false;
    });
};

