Instead of Object.keys(source).every(), would doing a for loop be better? Example:
JavaScript:
function objectsMatch(source, target) {
    for (const key in target) {
        if (!source[key]) return false;
        const typeA = Object.prototype.toString.call(source[key]);
        const typeB = Object.prototype.toString.call(target[key]);
        if (typeA !== typeB) return false;
        if (source[key] instanceof Array) {
            // still using Array.prototype.matches in this case
            if (!source[key].matches(target[key])) return false;
        } else if (typeA === "[object Object]") {
            if (!objectsMatch(source[key], target[key])) return false;
        } else if (source[key] !== target[key]) {
            return false;
        }
    }
    return true;
}
